implementation:
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/spinlock.h>
#include <linux/wait.h>
#include <linux/usb.h>

ssize_t hid_gadget_write(struct file *file, const char __user *buffer, size_t count, loff_t *offp)
{
    struct hid_gadget_request *req;
    ssize_t bytes_written = 0;
    int ret = 0;

    if (!access_ok(VERIFY_READ, buffer, count)) {
        return -EFAULT;
    }

    spin_lock(&hid_gadget_lock);

    while (hid_gadget_write_pending) {
        ret = wait_event_interruptible(hid_gadget_write_wait, !hid_gadget_write_pending);
        if (ret < 0) {
            spin_unlock(&hid_gadget_lock);
            return ret;
        }
    }

    req = hid_gadget_alloc_request();
    if (!req) {
        spin_unlock(&hid_gadget_lock);
        return -ENOMEM;
    }

    if (copy_from_user(req->data, buffer, count)) {
        hid_gadget_free_request(req);
        spin_unlock(&hid_gadget_lock);
        return -EFAULT;
    }

    req->length = count;

    if (hid_gadget_queue_request(req) < 0) {
        hid_gadget_free_request(req);
        hid_gadget_write_pending = 0;
        wake_up_interruptible(&hid_gadget_write_wait);
        spin_unlock(&hid_gadget_lock);
        return -EIO;
    }

    bytes_written = count;

    hid_gadget_write_pending = 1;
    wake_up_interruptible(&hid_gadget_write_wait);
    spin_unlock(&hid_gadget_lock);

    return bytes_written;
}
